@EnabledIfEnvironmentVariable(named="STUDYROOM_INTEGRATION",matches="true")
@SpringBootTest(properties={"spring.datasource.url=${STUDYROOM_TEST_DB_URL:jdbc:postgresql://127.0.0.1:5433/studyroom_java_test}","studyroom.seed=false","studyroom.scheduler-enabled=false"})
@AutoConfigureMockMvc(print=MockMvcPrint.NONE)
class ManualViolationIntegrationTest {
    @TestConfiguration static class TimeConfig { @Bean @Primary MinuteBookingIntegrationTest.TestClock testClock() { var c=new MinuteBookingIntegrationTest.TestClock();c.set(LocalDate.now(BookingPolicy.CAMPUS_ZONE).minusDays(1).atTime(9,0));return c; } }
    @Autowired Store db;
    @Autowired BookingService bookings;
    @Autowired SeatCodeService codes;
    @Autowired OpeningScheduleService opening;
    @Autowired ResourceService resources;
    @Autowired ComplaintService complaints;
    @Autowired ComplaintManagementService management;
    @Autowired ComplaintWorkflowService workflow;
    @Autowired ViolationService violations;
    @Autowired AttachmentService attachments;
    @Autowired org.springframework.transaction.support.TransactionTemplate transactions;
    @Autowired MinuteBookingIntegrationTest.TestClock clock;
    @Autowired MockMvc http;
    @Autowired ObjectMapper json;
    @Autowired StringRedisTemplate redis;
    long admin,admin2,student,staff,other,room,seat1,seat2;
    LocalDate base;
    String remote;
    @BeforeEach void fixture() {
        assertEquals("studyroom_java_test",db.one("SELECT current_database() AS name").get("name"));
        TestDatabaseCleanup.clear(db);
        base=LocalDate.now(BookingPolicy.CAMPUS_ZONE).minusDays(1);clock.set(base.atTime(9,0));remote="s14-test-"+UUID.randomUUID();
        String hash=new BCryptPasswordEncoder().encode("S02-test-only-password");
        admin=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s14_admin',?,'admin','S09-admin')",hash);
        admin2=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s14_admin2',?,'admin','S15-admin2')",hash);
        student=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s14_student',?,'student','S09-student')",hash);
        staff=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s14_staff',?,'staff','S09-staff')",hash);
        other=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s14_other',?,'student','S14-other')",hash);
        db.update("UPDATE users SET real_name='S15模拟管理员甲' WHERE id=?",admin);
        room=db.insert("INSERT INTO rooms(name,seat_rows,seat_cols) VALUES('S14模拟空间',1,2)");opening.initializeDefaults(room);
        seat1=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'01',1,1)",room);seat2=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'02',1,2)",room);
    }
    @AfterEach void clearRate() { redis.delete("studyroom-java:rate:login:"+remote); }
    void at(int h,int m,int s) { clock.set(base.atTime(h,m,s)); }
    String token(String role) throws Exception {
        var result=http.perform(post("/api/auth/login").with(r->{r.setRemoteAddr(remote);return r;}).contentType("application/json").content(json.writeValueAsString(Map.of("username","s14_"+role,"password","S02-test-only-password")))).andExpect(status().isOk()).andReturn();
        return json.readTree(result.getResponse().getContentAsString()).path("data").path("token").asText();
    }
    long reservation(long user,long seat) { return Store.id(bookings.create(user,new Requests.Reservation(seat,base.toString(),"10:00","11:00")),"id"); }
    String code(long seat) { codes.generate(admin,seat,new Requests.SeatCodeChange(0L,"测试实际生成座位码"));return current(seat); }
    String current(long seat) { return Store.text(db.one("SELECT code_value FROM seat_codes WHERE seat_id=?",seat),"code_value"); }
    MockHttpServletRequestBuilder auth(MockHttpServletRequestBuilder req,String token) { return req.header("Authorization","Bearer "+token); }
    MockHttpServletRequestBuilder checkin(long id,String code,String token) throws Exception { return auth(post("/api/reservations/"+id+"/checkin"),token).contentType("application/json").content(json.writeValueAsString(Map.of("seat_code",code))); }
    Map<String,Object> row(long id) { return db.one("SELECT * FROM reservations WHERE id=?",id); }


    long sourceReservation;
    String key(){return UUID.randomUUID().toString();}
    long source(){return source(staff,"10:05:00.123456","verified_refusal");}
    long source(long subject,String time,String outcome){if(sourceReservation==0){clock.set(base.atTime(9,0));sourceReservation=reservation(student,seat1);}clock.set(base.atTime(10,6));long complaint=Store.id(complaints.create(student,new Requests.Complaint("occupation",sourceReservation,null,"S18工程模拟：本人预约被占核实，不自动认定或处罚",List.of(),key())),"id");management.accept(admin,complaint,new Requests.ComplaintAccept(1L,key()));clock.set(base.atTime(10,30,0,123456000));var result=management.verify(admin,complaint,new Requests.ComplaintVerification(2L,key(),outcome,base+"T"+time+"+08:00","管理员主动公开核查进度","PRIVATE-FACT-SENTINEL 工程模拟私有事实说明",subject,subject!=0,subject==0?null:"PRIVATE-IDENTITY-SENTINEL 工程模拟身份依据",true,true));return Store.id(result,"event_id");}
    Requests.ManualViolation request(){return new Requests.ManualViolation(key(),"PUBLIC-REASON 工程模拟核实后的拒不配合事实说明");}
    String path(long event){return "/api/admin/complaint-events/"+event+"/violations";}
    MockHttpServletRequestBuilder body(MockHttpServletRequestBuilder req,Object value,String token)throws Exception{return auth(req,token).contentType("application/json").content(json.writeValueAsString(value));}
    String facts(){var all=new LinkedHashMap<String,Object>();for(String table:List.of("violations","notifications","audit_events","complaints","complaint_events","complaint_targets","complaint_target_events","reservations","usage_records","credit_logs","reminders"))all.put(table,db.list("SELECT to_jsonb(t)::text AS raw FROM "+table+" t ORDER BY to_jsonb(t)::text"));return all.toString();}
    String unchangedDomain(){var all=new LinkedHashMap<String,Object>();for(String table:List.of("complaints","complaint_events","complaint_targets","complaint_target_events","reservations","usage_records","credit_logs","reminders"))all.put(table,db.list("SELECT to_jsonb(t)::text AS raw FROM "+table+" t ORDER BY to_jsonb(t)::text"));return all.toString();}
    @SuppressWarnings("unchecked") Map<String,Object> violation(Map<String,Object> receipt){return (Map<String,Object>)receipt.get("violation");}
    @Test void realHttpRegistrationUsesImmutableSourceAndCreatesTypedNotificationWithSafeOwnerDto()throws Exception{
        String adminToken=token("admin"),subjectToken=token("staff");long event=source();String before=unchangedDomain();var request=request();var result=http.perform(body(post(path(event)),request,adminToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data.replayed").value(false)).andExpect(jsonPath("$.data.violation.user_id").value(staff)).andExpect(jsonPath("$.data.violation.reservation_id").value(sourceReservation)).andExpect(jsonPath("$.data.violation.source_event_id").value(event)).andExpect(jsonPath("$.data.violation.type").value("occupation_refusal")).andExpect(jsonPath("$.data.violation.source").value("manual")).andExpect(jsonPath("$.data.violation.occurred_at").value(base+"T10:05:00.123456+08:00")).andExpect(jsonPath("$.data.violation.notified_at").value(base+"T10:30:00.123456+08:00")).andReturn();long id=json.readTree(result.getResponse().getContentAsString()).path("data").path("violation").path("id").asLong();
        assertEquals(before,unchangedDomain());assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE violation_id=? AND user_id=? AND type='violation'",id,staff));assertEquals(1,db.count("SELECT count(*) FROM audit_events WHERE action='violation.register_manual'"));http.perform(auth(get("/api/violations/mine"),subjectToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data.items[0].id").value(id)).andExpect(jsonPath("$.data.items[0].reservation_id").isEmpty()).andExpect(jsonPath("$.data.items[0].reason").value(request.reason())).andExpect(jsonPath("$.data.items[0].registrant_display_name").value("S15模拟管理员甲")).andExpect(jsonPath("$.data.items[0].source_event_id").doesNotExist());
    }
    @Test void ordinaryAnonymousDisabledAdministratorAndUnknownEventCannotRegister()throws Exception{
        String studentToken=token("student"),staffToken=token("staff"),adminToken=token("admin");long event=source();String before=facts();http.perform(post(path(event)).contentType("application/json").content("{}" )).andExpect(status().isUnauthorized());for(String ordinary:List.of(studentToken,staffToken))http.perform(body(post(path(event)),request(),ordinary)).andExpect(status().isForbidden());assertEquals(403,assertThrows(Api.Failure.class,()->violations.registerManual(student,event,request())).status);http.perform(body(post(path(Long.MAX_VALUE)),request(),adminToken)).andExpect(status().isNotFound());db.update("UPDATE users SET status='disabled' WHERE id=?",admin);assertEquals(403,assertThrows(Api.Failure.class,()->violations.registerManual(admin,event,request())).status);db.update("UPDATE users SET status='active' WHERE id=?",admin);assertEquals(before,facts());
    }
    @Test void disabledOrdinarySubjectStillRegistersButAdminSubjectOnlyKeepsFacts()throws Exception{
        long ordinary=source();db.update("UPDATE users SET status='disabled' WHERE id=?",staff);var result=violations.registerManual(admin,ordinary,request());assertEquals(staff,Store.id(violation(result),"user_id"));assertNotNull(violation(result).get("notified_at"));long adminSource=source(admin2,"10:06:00","verified_refusal");assertEquals(400,assertThrows(Api.Failure.class,()->violations.registerManual(admin,adminSource,request())).status);assertEquals(2,db.count("SELECT count(*) FROM complaint_events WHERE outcome='verified_refusal'"));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE source='manual'"));
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"identity_pending","unsubstantiated","cooperated","service_verified"})
    void nonRefusalOutcomesCannotBeConvertedToPunishment(String outcome){long event;if(outcome.equals("service_verified")){clock.set(base.atTime(10,30));long id=Store.id(complaints.create(student,new Requests.Complaint("service",null,null,"普通服务核实不处罚",List.of(),key())),"id");management.accept(admin,id,new Requests.ComplaintAccept(1L,key()));event=Store.id(management.verify(admin,id,new Requests.ComplaintVerification(2L,key(),outcome,base+"T10:05:00+08:00","public","private",null,false,null,true,false)),"event_id");}else if(outcome.equals("identity_pending")){long valid=source();var c=db.one("SELECT complaint_id FROM complaint_events WHERE id=?",valid);event=Store.id(management.verify(admin,Store.id(c,"complaint_id"),new Requests.ComplaintVerification(3L,key(),outcome,base+"T10:05:00+08:00","public","identity unknown",null,false,null,true,true)),"event_id");}else event=source(staff,"10:05:00",outcome);String before=facts();assertEquals(400,assertThrows(Api.Failure.class,()->violations.registerManual(admin,event,request())).status);assertEquals(before,facts());}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"unknown_identity","facts_false","rights_false","identity_blank","private_fact_blank","outside_original_slot","future_fact","reporter_subject","wrong_complaint_type"})
    void databaseLegalButUnqualifiedHistoricalSourceIsRevalidated(String problem){long event=source();String change=switch(problem){case "unknown_identity"->"subject_user_id=NULL,identity_confirmed=false,identity_basis=NULL";case "facts_false"->"facts_confirmed=false";case "rights_false"->"valid_reservation_confirmed=false";case "identity_blank"->"identity_basis=' '";case "private_fact_blank"->"private_note=''";case "outside_original_slot"->"occurred_at=TIMESTAMP '"+base+" 09:59:59.999999'";case "future_fact"->"occurred_at=TIMESTAMP '"+base+" 10:45'";case "reporter_subject"->"subject_user_id="+student;default->null;};if(change!=null)db.update("UPDATE complaint_events SET "+change+" WHERE id=?",event);else db.update("UPDATE complaints SET type='service' WHERE id=(SELECT complaint_id FROM complaint_events WHERE id=?)",event);String before=facts();assertEquals(400,assertThrows(Api.Failure.class,()->violations.registerManual(admin,event,request())).status);assertEquals(before,facts());}
    @Test void currentClosedComplaintAndEndedReservationDoNotEraseVerifiedHistoricalFact(){long event=source();long complaint=Store.id(db.one("SELECT complaint_id FROM complaint_events WHERE id=?",event),"complaint_id");workflow.feedback(admin,complaint,new Requests.ComplaintFeedback(3L,key(),"formal result","public basis"));workflow.action(student,complaint,"confirm",new Requests.ComplaintResponse(4L,key(),null));bookings.mine(student);assertEquals("unused_ended",row(sourceReservation).get("status"));String before=unchangedDomain();var result=violations.registerManual(admin,event,request());assertEquals("manual",violation(result).get("source"));assertEquals(before,unchangedDomain());assertEquals("closed",db.one("SELECT status FROM complaints WHERE id=?",complaint).get("status"));}
    @Test void sameOperationIsDurableZeroWriteAndActorEventOrReasonChangesConflict(){long event=source();var request=request();var first=violations.registerManual(admin,event,request);String before=facts();db.update("UPDATE users SET role='admin' WHERE id=?",staff);String changed=facts();assertEquals(true,violations.registerManual(admin,event,request).get("replayed"));assertEquals(first.get("violation"),violations.registerManual(admin,event,request).get("violation"));assertEquals(changed,facts());db.update("UPDATE users SET role='staff' WHERE id=?",staff);assertEquals(before,facts());assertEquals(409,assertThrows(Api.Failure.class,()->violations.registerManual(admin2,event,request)).status);assertEquals(409,assertThrows(Api.Failure.class,()->violations.registerManual(admin,event,new Requests.ManualViolation(request.operationId(),"changed reason"))).status);long another=source(staff,"10:06:00","verified_refusal");assertEquals(409,assertThrows(Api.Failure.class,()->violations.registerManual(admin,another,request)).status);}
    @Test void duplicateEventAndSameFactAcrossComplaintsReturnExistingIdEvenIfRevoked()throws Exception{
        String adminToken=token("admin");long firstEvent=source();long id=Store.id(violation(violations.registerManual(admin,firstEvent,request())),"id");String before=facts();http.perform(body(post(path(firstEvent)),request(),adminToken)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.existing_violation_id").value(id)).andExpect(jsonPath("$.details.duplicate_by").value("source_event"));assertEquals(before,facts());long secondEvent=source();db.update("UPDATE violations SET status='revoked' WHERE id=?",id);before=facts();http.perform(body(post(path(secondEvent)),request(),adminToken)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.existing_violation_id").value(id)).andExpect(jsonPath("$.details.duplicate_by").value("fact"));assertEquals(before,facts());long complaint=Store.id(db.one("SELECT complaint_id FROM complaint_events WHERE id=?",secondEvent),"complaint_id");String projected=json.writeValueAsString(management.detail(admin,complaint));assertTrue(projected.contains("existing_violation"));assertTrue(projected.contains("revoked"));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE source='manual'"));}
    @Test void separateMicrosecondFactsForSameReservationAndPersonRemainIndependent(){long a=source(staff,"10:05:00.123456","verified_refusal"),b=source(staff,"10:05:00.123457","verified_refusal");violations.registerManual(admin,a,request());violations.registerManual(admin,b,request());assertEquals(2,db.count("SELECT count(*) FROM violations WHERE source='manual'"));assertNotEquals(db.one("SELECT occurred_at FROM violations WHERE source_event_id=?",a).get("occurred_at"),db.one("SELECT occurred_at FROM violations WHERE source_event_id=?",b).get("occurred_at"));}
    @Test void concurrentSameKeyAndDifferentKeySameFactNeverDuplicateNotificationsOrAudit()throws Exception{long a=source(),b=source();var request=request();var barrier=new CyclicBarrier(3);var pool=Executors.newFixedThreadPool(3);try{var jobs=List.of(pool.submit(()->{barrier.await();return violations.registerManual(admin,a,request);}),pool.submit(()->{barrier.await();return violations.registerManual(admin,a,request);}),pool.submit(()->{barrier.await();try{return violations.registerManual(admin2,b,request());}catch(Api.Failure failure){assertEquals(409,failure.status);return failure.status;}}));for(var job:jobs){try{job.get(20,TimeUnit.SECONDS);}catch(ExecutionException failure){assertTrue(failure.getCause() instanceof Api.Failure&&((Api.Failure)failure.getCause()).status==409);}}}finally{pool.shutdownNow();}assertEquals(1,db.count("SELECT count(*) FROM violations WHERE source='manual'"));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE violation_id IS NOT NULL"));assertEquals(1,db.count("SELECT count(*) FROM audit_events WHERE action='violation.register_manual'"));}
    @Test void publicAffectedAndReporterViewsNeverLeakSourceOrPrivateIdentity()throws Exception{String affected=token("staff"),reporter=token("student");long event=source();db.update("UPDATE users SET real_name='REPORTER-NAME-SECRET',campus_id='REPORTER-CAMPUS-X',phone='REPORTER-PHONE-SECRET',email='REPORTER-EMAIL-SECRET@example.test' WHERE id=?",student);var result=violations.registerManual(admin,event,request());long id=Store.id(violation(result),"id");for(String endpoint:List.of("/api/violations/mine","/api/notifications")){String raw=http.perform(auth(get(endpoint),affected)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);for(String secret:List.of("REPORTER-NAME-SECRET","REPORTER-CAMPUS-X","REPORTER-PHONE-SECRET","REPORTER-EMAIL-SECRET","PRIVATE-FACT-SENTINEL","PRIVATE-IDENTITY-SENTINEL","source_event_id","reporter_id"))assertFalse(raw.contains(secret),secret);assertTrue(raw.contains("PUBLIC-REASON"));}assertTrue(violations.mine(student).stream().noneMatch(v->Store.id(v,"id")==id));var own=violations.mine(staff).get(0);assertEquals(Set.of("id","reservation_id","type","occurred_at","registered_at","status","reason","source","registrant_display_name","notification_id","notified_at","revocation"),own.keySet());assertNull(own.get("revocation"));assertNull(own.get("reservation_id"));}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"violation","notification","audit"})
    void manualRegistrationAnyDependencyFailureRollsBackRecordOperationNotificationAndAudit(String layer)throws Exception{String token=token("admin");long event=source();String before=facts();String table=layer.equals("violation")?"violations":layer.equals("notification")?"notifications":"audit_events",condition=layer.equals("violation")?"source<>'manual'":layer.equals("notification")?"violation_id IS NULL":"action<>'violation.register_manual'";db.update("ALTER TABLE "+table+" ADD CONSTRAINT s18_fail CHECK("+condition+") NOT VALID");try{http.perform(body(post(path(event)),request(),token)).andExpect(status().isInternalServerError());assertEquals(before,facts());}finally{db.update("ALTER TABLE "+table+" DROP CONSTRAINT s18_fail");}}
    @Test void automaticUnusedUsesOriginalSingleNotificationWithRealTypedTime(){long reservation=reservation(student,seat1);clock.set(base.atTime(10,15,0,123456000));bookings.mine(student);assertEquals(1,db.count("SELECT count(*) FROM violations WHERE source='automatic'"));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='violation'"));var v=violations.mine(student).get(0);assertEquals(reservation,Store.id(v,"reservation_id"));assertEquals("automatic",v.get("source"));assertNotNull(v.get("notification_id"));assertEquals(base+"T10:15:00.123456+08:00",v.get("notified_at"));String before=facts();bookings.mine(student);assertEquals(before,facts());}
    @Test void oldAutomaticAndPlausibleUnlinkedNotificationKeepUnknownNotifiedTime(){long reservation=reservation(student,seat1);long id=db.insert("INSERT INTO violations(user_id,reservation_id,type,event_key,occurred_at,registered_at,reason,source) VALUES(?,?,'abandon','legacy-unused',?,?,'S18明确旧自动历史模拟','automatic')",student,reservation,java.sql.Timestamp.valueOf(base.atTime(10,1)),java.sql.Timestamp.valueOf(base.atTime(10,2)));db.update("INSERT INTO notifications(user_id,type,title,content,created_at) VALUES(?,'violation','旧违规通知','相似时间文字不能证明typed关联',?)",student,java.sql.Timestamp.valueOf(base.atTime(10,2)));var v=violations.mine(student).stream().filter(row->Store.id(row,"id")==id).findFirst().orElseThrow();assertNull(v.get("notification_id"));assertNull(v.get("notified_at"));}
    @Test void sourceEligibilityAndJsonWhitelistCannotBeOverriddenByClient()throws Exception{String token=token("admin");long event=source();for(String field:List.of("subject_user_id","reservation_id","type","occurred_at","version","actor_id")){var bad=new LinkedHashMap<String,Object>();bad.put("operation_id",key());bad.put("reason","public");bad.put(field,staff);http.perform(body(post(path(event)),bad,token)).andExpect(status().isBadRequest());}for(String reason:List.of(" ","x".repeat(1001)))http.perform(body(post(path(event)),new Requests.ManualViolation(key(),reason),token)).andExpect(status().isBadRequest());long complaint=Store.id(db.one("SELECT complaint_id FROM complaint_events WHERE id=?",event),"complaint_id");String before=http.perform(auth(get("/api/admin/complaints/"+complaint),token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertTrue(json.readTree(before).path("data").path("admin_events").findValues("violation_registration").stream().anyMatch(node->node.path("eligible").asBoolean()));violations.registerManual(admin,event,request());var after=json.readTree(http.perform(auth(get("/api/admin/complaints/"+complaint),token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());assertTrue(after.path("data").path("admin_events").findValues("violation_registration").stream().anyMatch(node->node.path("existing_violation").path("id").isNumber()));}
}
